-- 0151 — O NAS V2: the about page as a product page (nine about_* sections).
--
-- GENERATED from lib/cms-seed.ts by `npm run cms:seed-sql -- --about-v2`. Do
-- not edit by hand: change the TypeScript and regenerate.
--
-- Content only: no table, no column, no function. The pictures are media
-- slots (about.*), empty until an admin fills them in "Edytuj stronę"; the
-- page draws neutral canvases until then. The sixth value and the questions
-- about photos and company details are switched OFF and hold placeholders —
-- the renderer never shows a "[…]" text, switched on or not.

do $about$
declare
  v_page uuid;
  v_seo jsonb;
  v_snapshot jsonb;
begin
  insert into public.cms_pages (slug, title, status, kind)
  values ('o-nas', 'O nas', 'draft', 'standard')
  on conflict (slug) do nothing;
  select id into v_page from public.cms_pages where slug = 'o-nas';

  if exists (select 1 from public.cms_blocks b where b.page_id = v_page and b.type = 'about_hero') then
    raise notice 'o-nas: already on the O nas V2 layout, nothing written';
    return;
  end if;

  -- 1. Keep what is being replaced.
  if exists (select 1 from public.cms_blocks b where b.page_id = v_page) then
    insert into public.cms_page_versions (page_id, version, snapshot, seo, reason, label)
    select v_page,
           coalesce((select max(v.version) from public.cms_page_versions v where v.page_id = v_page), 0) + 1,
           (select jsonb_agg(jsonb_build_object(
            'id', b.id, 'type', b.type, 'sort_order', b.sort_order,
            'visible', b.visible, 'content', b.content,
            'style', b.style, 'code', b.code,
            'analytics_id', b.analytics_id, 'anchor', b.anchor,
            'show_from', b.show_from, 'show_until', b.show_until,
            'audience', b.audience
          ) order by b.sort_order)
              from public.cms_blocks b where b.page_id = v_page),
           coalesce((select p.seo from public.cms_pages p where p.id = v_page), '{}'::jsonb),
           'manual',
           'Przed O nas V2';
  end if;

  -- 2. The new sections.
  delete from public.cms_blocks where page_id = v_page;
  insert into public.cms_blocks (page_id, sort_order, type, content, style, anchor, analytics_id)
  select v_page, v.sort_order, v.type, v.content, v.style, v.anchor, v.analytics_id
  from (values
      (0, 'about_hero', '{"badge":{"pl":"O NAS","en":"ABOUT US","de":"ÜBER UNS"},"title":{"pl":"Dobre zdjęcie produktu nie powinno kosztować więcej niż marża na produkcie","en":"A good product photo shouldn’t cost more than the margin on the product","de":"Ein gutes Produktfoto sollte nicht mehr kosten als die Marge auf das Produkt"},"subtitle":{"pl":"GrovBase robi z prostego zdjęcia z telefonu gotowe materiały do sprzedaży. Bez studia, bez promptów i bez czekania na grafika.","en":"GrovBase turns a simple phone photo into ready-to-sell material. No studio, no prompts and no waiting for a designer.","de":"GrovBase macht aus einem einfachen Handyfoto fertiges Verkaufsmaterial. Ohne Studio, ohne Prompts und ohne Warten auf einen Grafiker."}}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"md","width":"wide"}}'::jsonb, null, 'about.hero'),
      (1, 'about_story', '{"title":{"pl":"Skąd się wzięliśmy","en":"Where we come from","de":"Woher wir kommen"},"description":{"pl":"Od ponad pięciu lat robimy grafiki dla sprzedawców z Allegro i innych marketplace’ów. Popyt na dobre miniaturki i zdjęcia produktów był tak duży, że nie dało się przyjąć wszystkich zleceń, a sprzedawcy czekali dniami na coś, co powinno zająć minuty.\n\nNarzędzia AI, które testowaliśmy, dawały efekt „typowego AI”, wymagały pisania promptów albo robiły tylko jedną rzecz. Postanowiliśmy więc zamknąć nasz warsztat w aplikacji, z której każdy sprzedawca może skorzystać sam.","en":"For more than five years we have been creating graphics for sellers on Allegro and other marketplaces. Demand for good thumbnails and product photos was so high that we couldn’t take on every order, and sellers waited days for something that should take minutes.\n\nThe AI tools we tested produced that “typical AI” look, required writing prompts or did only one thing. So we decided to put our workshop into an app that any seller can use on their own.","de":"Seit mehr als fünf Jahren gestalten wir Grafiken für Händler auf Allegro und anderen Marktplätzen. Die Nachfrage nach guten Thumbnails und Produktfotos war so groß, dass wir nicht alle Aufträge annehmen konnten – und Händler tagelang auf etwas warteten, das Minuten dauern sollte.\n\nDie KI-Werkzeuge, die wir getestet haben, lieferten den typischen „KI-Look“, verlangten das Schreiben von Prompts oder konnten nur eine Sache. Also haben wir unsere Werkstatt in eine App gepackt, die jeder Händler selbst nutzen kann."},"ctaLabel":{"pl":"Wypróbuj za darmo","en":"Try it for free","de":"Kostenlos ausprobieren"}}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"lg"}}'::jsonb, 'historia', 'about.story'),
      (2, 'about_process', '{"badge":{"pl":"JAK TO DZIAŁA","en":"HOW IT WORKS","de":"SO FUNKTIONIERT ES"},"title":{"pl":"Projektuje grafik, wykonuje AI","en":"A designer designs, AI delivers","de":"Ein Grafiker gestaltet, die KI setzt um"},"items":[{"icon":"pen","title":{"pl":"Grafik projektuje efekt","en":"A designer designs the effect","de":"Ein Grafiker gestaltet den Effekt"},"description":{"pl":"Każde narzędzie ustawia grafik e-commerce: kompozycję, światło, cienie i wymagania marketplace’ów. To te same zasady, według których robimy grafiki ręcznie.","en":"Every tool is set up by an e-commerce designer: composition, light, shadows and marketplace requirements. The same rules we follow when we make graphics by hand.","de":"Jedes Werkzeug richtet ein E-Commerce-Grafiker ein: Komposition, Licht, Schatten und die Anforderungen der Marktplätze. Dieselben Regeln, nach denen wir Grafiken von Hand erstellen."}},{"icon":"wand","title":{"pl":"AI go wykonuje","en":"AI carries it out","de":"Die KI setzt ihn um"},"description":{"pl":"Do każdego zadania dobieramy model, który daje najlepszy efekt, i wymieniamy go, gdy pojawi się lepszy.","en":"For every task we pick the model that gives the best result, and we replace it when a better one comes along.","de":"Für jede Aufgabe wählen wir das Modell, das das beste Ergebnis liefert, und tauschen es aus, sobald es ein besseres gibt."}},{"icon":"download","title":{"pl":"Ty dostajesz gotowy plik","en":"You get a finished file","de":"Du bekommst eine fertige Datei"},"description":{"pl":"Wgrywasz zdjęcie, wybierasz efekt i pobierasz grafikę gotową do wystawienia oferty.","en":"Upload a photo, choose an effect and download a graphic ready for your listing.","de":"Foto hochladen, Effekt wählen und eine Grafik herunterladen, die bereit fürs Angebot ist."}}]}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"lg","background":"sunken"}}'::jsonb, 'jak-to-dziala', 'about.process'),
      (3, 'about_importance', '{"title":{"pl":"Dlaczego zdjęcie ma znaczenie","en":"Why the photo matters","de":"Warum das Foto zählt"},"description":{"pl":"Na liście ofert kupujący widzi najpierw miniaturkę, dopiero potem cenę i opis. Zdjęcie decyduje, czy w ogóle kliknie. A dobra sesja to termin, studio, fotograf, retusz i tydzień czekania – na produkt, który może się nie sprzedać. GrovBase skraca to do kilku minut, a koszt do ułamka.","en":"In a list of offers the buyer sees the thumbnail first and only then the price and description. The photo decides whether they click at all. And a good shoot means a booking, a studio, a photographer, retouching and a week of waiting – for a product that might not sell. GrovBase cuts that to a few minutes and the cost to a fraction.","de":"In einer Angebotsliste sieht der Käufer zuerst das Thumbnail, erst danach Preis und Beschreibung. Das Foto entscheidet, ob er überhaupt klickt. Und ein gutes Shooting heißt Termin, Studio, Fotograf, Retusche und eine Woche Warten – für ein Produkt, das sich vielleicht nicht verkauft. GrovBase verkürzt das auf wenige Minuten und die Kosten auf einen Bruchteil."},"ctaLabel":{"pl":"Zobacz przykłady","en":"See examples","de":"Beispiele ansehen"},"ctaUrl":"/narzedzia"}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"lg"}}'::jsonb, null, 'about.importance'),
      (4, 'about_values', '{"badge":{"pl":"NASZE ZASADY","en":"OUR PRINCIPLES","de":"UNSERE GRUNDSÄTZE"},"title":{"pl":"W co wierzymy","en":"What we believe","de":"Woran wir glauben"},"items":[{"icon":"target","title":{"pl":"Wierność przed kreatywnością","en":"Fidelity before creativity","de":"Treue vor Kreativität"},"description":{"pl":"Ładne zdjęcie, na którym produkt wygląda inaczej niż w rzeczywistości, to zwrot i zła opinia. Kształt, kolor i detal są ważniejsze niż efekt.","en":"A pretty photo in which the product looks different than in reality means a return and a bad review. Shape, colour and detail matter more than the effect.","de":"Ein schönes Foto, auf dem das Produkt anders aussieht als in Wirklichkeit, bedeutet eine Rücksendung und eine schlechte Bewertung. Form, Farbe und Details sind wichtiger als der Effekt."}},{"icon":"zap","title":{"pl":"Bez promptów","en":"No prompts","de":"Ohne Prompts"},"description":{"pl":"Sprzedawca ma sprzedawać, nie uczyć się pisania poleceń dla AI. Wgrywasz zdjęcie, wybierasz efekt, gotowe.","en":"A seller should be selling, not learning to write instructions for AI. Upload a photo, choose an effect, done.","de":"Ein Händler soll verkaufen, nicht lernen, Anweisungen für KI zu schreiben. Foto hochladen, Effekt wählen, fertig."}},{"icon":"pen","title":{"pl":"Zaprojektowane w praktyce","en":"Designed in practice","de":"In der Praxis entworfen"},"description":{"pl":"Efekty powstają na bazie tysięcy grafik wykonanych dla prawdziwych sprzedawców, a nie z myślą o ładnym demo.","en":"Our effects are built on thousands of graphics made for real sellers, not with a pretty demo in mind.","de":"Unsere Effekte basieren auf Tausenden Grafiken für echte Händler, nicht auf einer hübschen Demo."}},{"icon":"layers","title":{"pl":"Najlepszy model do zadania","en":"The best model for the job","de":"Das beste Modell für die Aufgabe"},"description":{"pl":"Modele AI zmieniają się co kilka miesięcy. Nie jesteśmy przywiązani do jednego dostawcy.","en":"AI models change every few months. We are not tied to a single provider.","de":"KI-Modelle ändern sich alle paar Monate. Wir sind an keinen einzelnen Anbieter gebunden."}},{"icon":"eye","title":{"pl":"Bez udawania","en":"No pretending","de":"Kein Vortäuschen"},"description":{"pl":"Funkcja, która jeszcze nie działa, jest oznaczona jako „wkrótce”. Nie pokazujemy przycisków, które nic nie robią.","en":"A feature that doesn’t work yet is marked “coming soon”. We don’t show buttons that do nothing.","de":"Eine Funktion, die noch nicht funktioniert, ist als „bald verfügbar“ gekennzeichnet. Wir zeigen keine Schaltflächen, die nichts tun."}},{"hidden":true,"icon":"lock","title":{"pl":"Twoje zdjęcia są Twoje","en":"Your photos are yours","de":"Deine Fotos gehören dir"},"description":{"pl":"[treść do potwierdzenia]","en":"[content to be confirmed]","de":"[Inhalt zu bestätigen]"}}]}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"lg","background":"sunken"}}'::jsonb, 'zasady', 'about.values'),
      (5, 'about_audience', '{"badge":{"pl":"DLA KOGO","en":"WHO IT’S FOR","de":"FÜR WEN"},"title":{"pl":"Dla każdego, kto sprzedaje online","en":"For everyone who sells online","de":"Für alle, die online verkaufen"},"items":[{"slot":"about.audience.small","icon":"bag","title":{"pl":"Mali sprzedawcy","en":"Small sellers","de":"Kleine Händler"},"description":{"pl":"Prowadzisz sklep sam i nie masz budżetu na sesję dla każdego produktu.","en":"You run your shop on your own and don’t have the budget for a shoot for every product.","de":"Du führst deinen Shop allein und hast kein Budget für ein Shooting für jedes Produkt."},"points":[{"icon":"clock","title":{"pl":"Miniaturka w kilka minut zamiast kilku dni","en":"A thumbnail in minutes instead of days","de":"Ein Thumbnail in Minuten statt Tagen"}},{"icon":"coins","title":{"pl":"Koszt kilku złotych zamiast kilkudziesięciu","en":"A few złoty instead of dozens","de":"Ein paar Złoty statt Dutzender"}},{"icon":"wand","title":{"pl":"Bez umiejętności graficznych","en":"No design skills needed","de":"Keine Grafikkenntnisse nötig"}},{"icon":"gift","title":{"pl":"Darmowe kredyty na start","en":"Free credits to start","de":"Kostenlose Credits zum Start"}}]},{"slot":"about.audience.large","icon":"company","title":{"pl":"Duzi sprzedawcy i marki","en":"Large sellers and brands","de":"Große Händler und Marken"},"description":{"pl":"Sprzedajesz w wielu kanałach i regularnie wprowadzasz nowe produkty.","en":"You sell across many channels and launch new products regularly.","de":"Du verkaufst über viele Kanäle und bringst regelmäßig neue Produkte heraus."},"points":[{"icon":"layers","title":{"pl":"Spójne zdjęcia dla całego asortymentu","en":"Consistent photos across your whole range","de":"Einheitliche Fotos für das ganze Sortiment"}},{"icon":"crop","title":{"pl":"Formaty pod Allegro, Amazon i własny sklep","en":"Formats for Allegro, Amazon and your own shop","de":"Formate für Allegro, Amazon und den eigenen Shop"}},{"icon":"images","title":{"pl":"Wiele zdjęć w jednej generacji","en":"Many photos in one generation","de":"Viele Fotos in einer Generierung"}},{"icon":"users","title":{"pl":"Plan dla zespołu","en":"A plan for your team","de":"Ein Plan für dein Team"}}]}]}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"lg"}}'::jsonb, 'dla-kogo', 'about.audience'),
      (6, 'about_team', '{"badge":{"pl":"ZESPÓŁ","en":"TEAM","de":"TEAM"},"title":{"pl":"Kto za tym stoi","en":"Who’s behind it","de":"Wer dahintersteht"},"items":[{"slot":"about.team.jakub","value":"J","title":{"pl":"Jakub","en":"Jakub","de":"Jakub"},"badge":{"pl":"Grafik e-commerce, współzałożyciel","en":"E-commerce designer, co-founder","de":"E-Commerce-Grafiker, Mitgründer"},"description":{"pl":"Od ponad pięciu lat projektuje miniaturki i zdjęcia produktów dla sprzedawców z marketplace’ów. W GrovBase odpowiada za to, jak wyglądają efekty każdego narzędzia.","en":"For more than five years he has been designing thumbnails and product photos for marketplace sellers. At GrovBase he is responsible for how every tool’s effects look.","de":"Seit mehr als fünf Jahren gestaltet er Thumbnails und Produktfotos für Marktplatz-Händler. Bei GrovBase verantwortet er, wie die Effekte jedes Werkzeugs aussehen."}},{"slot":"about.team.marcel","value":"M","title":{"pl":"Marcel","en":"Marcel","de":"Marcel"},"badge":{"pl":"Technologia, współzałożyciel","en":"Technology, co-founder","de":"Technologie, Mitgründer"},"description":{"pl":"Od ponad sześciu lat projektuje i buduje sklepy internetowe i strony. W GrovBase odpowiada za aplikację i to, żeby wszystko działało szybko i bez błędów.","en":"For more than six years he has been designing and building online shops and websites. At GrovBase he is responsible for the app and for everything working fast and without errors.","de":"Seit mehr als sechs Jahren konzipiert und baut er Onlineshops und Websites. Bei GrovBase verantwortet er die App und dass alles schnell und fehlerfrei läuft."}}]}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"lg","background":"sunken"}}'::jsonb, 'zespol', 'about.team'),
      (7, 'about_faq', '{"title":{"pl":"Masz pytania?","en":"Any questions?","de":"Noch Fragen?"},"items":[{"title":{"pl":"Czym jest GrovBase?","en":"What is GrovBase?","de":"Was ist GrovBase?"},"description":{"pl":"GrovBase to aplikacja dla sprzedawców e-commerce, która z prostego zdjęcia produktu robi gotowe materiały do sprzedaży: miniaturki, retusz, packshoty i zdjęcia lifestyle. Wgrywasz zdjęcie, wybierasz efekt i pobierasz plik gotowy do oferty.","en":"GrovBase is an app for e-commerce sellers that turns a simple product photo into ready-to-sell material: thumbnails, retouching, packshots and lifestyle photos. Upload a photo, choose an effect and download a file ready for your listing.","de":"GrovBase ist eine App für E-Commerce-Händler, die aus einem einfachen Produktfoto fertiges Verkaufsmaterial macht: Thumbnails, Retusche, Packshots und Lifestyle-Fotos. Foto hochladen, Effekt wählen und eine angebotsfertige Datei herunterladen."}},{"title":{"pl":"Kto stoi za GrovBase?","en":"Who is behind GrovBase?","de":"Wer steht hinter GrovBase?"},"description":{"pl":"GrovBase tworzą dwie osoby. Jakub jest grafikiem e-commerce i odpowiada za to, jak wyglądają efekty narzędzi. Marcel projektuje i buduje sklepy oraz aplikacje i odpowiada za technologię.","en":"GrovBase is made by two people. Jakub is an e-commerce designer and is responsible for how the tools’ effects look. Marcel designs and builds shops and apps and is responsible for the technology.","de":"GrovBase wird von zwei Personen entwickelt. Jakub ist E-Commerce-Grafiker und verantwortet, wie die Effekte der Werkzeuge aussehen. Marcel konzipiert und baut Shops und Apps und verantwortet die Technik."}},{"title":{"pl":"Na jakich modelach AI pracujecie?","en":"Which AI models do you use?","de":"Mit welchen KI-Modellen arbeitet ihr?"},"description":{"pl":"Korzystamy z modeli kilku dostawców i do każdego narzędzia dobieramy ten, który daje w nim najlepszy efekt. Gdy pojawi się lepszy model, możemy go wymienić — sposób korzystania z aplikacji się nie zmienia.","en":"We use models from several providers and, for each tool, pick the one that gives the best result there. When a better model appears we can switch to it — the way you use the app stays the same.","de":"Wir nutzen Modelle mehrerer Anbieter und wählen für jedes Werkzeug dasjenige, das dort das beste Ergebnis liefert. Gibt es ein besseres Modell, können wir wechseln – die Bedienung der App bleibt gleich."}},{"title":{"pl":"Czym różnicie się od innych narzędzi AI do zdjęć?","en":"How are you different from other AI photo tools?","de":"Was unterscheidet euch von anderen KI-Foto-Tools?"},"description":{"pl":"Efekty w GrovBase ustawia grafik e-commerce, więc nie musisz pisać promptów ani znać się na AI. Najważniejsza jest wierność produktu: kształt, kolory i detale mają pozostać takie, jak na Twoim zdjęciu.","en":"The effects in GrovBase are set up by an e-commerce designer, so you don’t need to write prompts or know anything about AI. Product fidelity comes first: shape, colours and details should stay as they are in your photo.","de":"Die Effekte in GrovBase richtet ein E-Commerce-Grafiker ein – du musst also keine Prompts schreiben und nichts über KI wissen. An erster Stelle steht die Produkttreue: Form, Farben und Details sollen so bleiben wie auf deinem Foto."}},{"hidden":true,"title":{"pl":"Co dzieje się z moimi zdjęciami?","en":"What happens to my photos?","de":"Was passiert mit meinen Fotos?"},"description":{"pl":"[treść do potwierdzenia]","en":"[content to be confirmed]","de":"[Inhalt zu bestätigen]"}},{"hidden":true,"title":{"pl":"Dane firmy","en":"Company details","de":"Firmendaten"},"description":{"pl":"[nazwa firmy], [miasto], NIP [numer]","en":"[company name], [city], VAT ID [number]","de":"[Firmenname], [Stadt], USt-IdNr. [Nummer]"}}]}'::jsonb, '{"base":{"paddingTop":"lg","paddingBottom":"md"}}'::jsonb, 'faq', 'about.faq'),
      (8, 'about_cta', '{"title":{"pl":"Sprzedawaj od pierwszego spojrzenia","en":"Sell from the first glance","de":"Verkaufe ab dem ersten Blick"},"subtitle":{"pl":"Gotowe zdjęcia produktów w kilka minut.","en":"Finished product photos in minutes.","de":"Fertige Produktfotos in wenigen Minuten."},"ctaLabel":{"pl":"Zacznij za darmo","en":"Start for free","de":"Kostenlos starten"},"cta2Label":{"pl":"Napisz do nas","en":"Write to us","de":"Schreib uns"},"cta2Url":"/kontakt"}'::jsonb, '{"base":{"paddingTop":"md","paddingBottom":"xl","width":"wide"}}'::jsonb, null, 'about.cta')
  ) as v(sort_order, type, content, style, anchor, analytics_id);

  -- 3. Menu group, SEO, the site's own chrome.
  v_seo := '{"pl":{"title":"O nas — GrovBase","description":"GrovBase robi z prostego zdjęcia z telefonu gotowe materiały do sprzedaży na Allegro, Amazon i we własnym sklepie. Poznaj ludzi i zasady, które za tym stoją."},"en":{"title":"About us — GrovBase","description":"GrovBase turns a simple phone photo into ready-to-sell material for Allegro, Amazon and your own shop. Meet the people and the principles behind it."},"de":{"title":"Über uns — GrovBase","description":"GrovBase macht aus einem einfachen Handyfoto fertiges Verkaufsmaterial für Allegro, Amazon und den eigenen Shop. Lerne die Menschen und Grundsätze dahinter kennen."}}'::jsonb;
  update public.cms_pages
     set nav_group = 'company',
         nav_order = 10,
         seo = v_seo,
         header_mode = 'global',
         footer_mode = 'global',
         updated_at = now()
   where id = v_page;

  -- 4. Publish, as publishPage does: the version first, then the page.
  select jsonb_agg(jsonb_build_object(
            'id', b.id, 'type', b.type, 'sort_order', b.sort_order,
            'visible', b.visible, 'content', b.content,
            'style', b.style, 'code', b.code,
            'analytics_id', b.analytics_id, 'anchor', b.anchor,
            'show_from', b.show_from, 'show_until', b.show_until,
            'audience', b.audience
          ) order by b.sort_order)
    into v_snapshot
    from public.cms_blocks b where b.page_id = v_page;
  insert into public.cms_page_versions (page_id, version, snapshot, seo, reason, label)
  values (
    v_page,
    coalesce((select max(v.version) from public.cms_page_versions v where v.page_id = v_page), 0) + 1,
    v_snapshot, v_seo, 'publish', 'O nas V2'
  );
  update public.cms_pages
     set published_snapshot = v_snapshot,
         status = 'published',
         published_at = now(),
         updated_at = now(),
         scheduled_at = null
   where id = v_page;
end $about$;
